
-- =====================================================================================
-- COMPLETE RESTORATION OF "Argus Technology" AND ALL 370 LEADS & CUSTOMERS
-- =====================================================================================

DO $$
DECLARE
  v_new_company_id uuid;
  v_technologies_id uuid;
BEGIN
  -- 1. Locate "Argus Technologies" (the existing one with 380 records)
  SELECT id INTO v_technologies_id 
  FROM public.companies 
  WHERE lower(company_name) = 'argus technologies' OR code = 'ARGUS'
  LIMIT 1;

  -- 2. Create or revive "Argus Technology" (the second company)
  SELECT id INTO v_new_company_id 
  FROM public.companies 
  WHERE lower(company_name) = 'argus technology' OR code = 'ARGUS_TECH'
  LIMIT 1;

  IF v_new_company_id IS NULL THEN
    VALUES (gen_random_uuid(), 'Argus Technology', 'ARGUS_TECH', 'Active', false)
    RETURNING id INTO v_new_company_id;
  ELSE
    UPDATE public.companies 
    SET company_name = 'Argus Technology', code = 'ARGUS_TECH', status = 'Active', updated_at = now()
    WHERE id = v_new_company_id;
  END IF;

  RAISE NOTICE 'Argus Technology ID: %, Argus Technologies ID: %', v_new_company_id, v_technologies_id;

  -- 3. Insert all 370 unique Customers for Argus Technology
  ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    contact = EXCLUDED.contact,
    phone = EXCLUDED.phone,
    email = EXCLUDED.email,
    city = EXCLUDED.city,
    gst = EXCLUDED.gst,
    company_id = EXCLUDED.company_id;

  -- 4. Also restore the customers for Argus Technologies if missing
  IF v_technologies_id IS NOT NULL THEN
    ON CONFLICT (id) DO UPDATE SET
      name = EXCLUDED.name,
      contact = EXCLUDED.contact,
      phone = EXCLUDED.phone,
      email = EXCLUDED.email,
      city = EXCLUDED.city,
      gst = EXCLUDED.gst,
      company_id = EXCLUDED.company_id;
  END IF;

  -- 5. Insert all 370 Enquiries for Argus Technology
  ON CONFLICT (id) DO UPDATE SET
    customer = EXCLUDED.customer,
    contact_person = EXCLUDED.contact_person,
    phone = EXCLUDED.phone,
    email = EXCLUDED.email,
    city = EXCLUDED.city,
    gst = EXCLUDED.gst,
    remarks = EXCLUDED.remarks,
    part_name = EXCLUDED.part_name,
    part_no = EXCLUDED.part_no,
    quantity = EXCLUDED.quantity,
    company_id = EXCLUDED.company_id;

  -- 6. Link user to Argus Technology as active company
  UPDATE public.company_users
  SET active_company_id = v_new_company_id, status = 'Active'
  WHERE email = 'jananimohan44@gmail.com' OR role = 'SUPER_ADMIN';

END $$;

-- Verify both companies and their record counts
SELECT 
  c.id, 
  c.company_name, 
  c.code, 
  c.status,
  (SELECT count(*) FROM public.cnc_enquiries e WHERE e.company_id = c.id) AS enquiries_count,
  (SELECT count(*) FROM public.cnc_customers cu WHERE cu.company_id = c.id) AS customers_count
FROM public.companies c;
